Do not permit checkpointer to be disabled (bit 6 unset) if chained signature is used. Revert in this case with custom error. Example fix in BaseSig.sol:
if (signatureFlag & 0x40 == 0) {
    revert MissingCheckpointer();
}

vulnerabilities.suggested_fix:
Wrap the permit call in a try-catch block and proceed with the unstake if allowance is already sufficient:

```solidity
function unstakeRequestWithPermit(...) external returns (uint256) {
    try mETH.permit(msg.sender, address(this), methAmount, deadline, v, r, s) {} catch {
        // Permit failed, check if allowance is already sufficient
        if (mETH.allowance(msg.sender, address(this)) < methAmount) {
            revert InsufficientAllowance();
        }
    }
    return _unstakeRequest(methAmount, minETHAmount);
}
```

Before attempting CREATE2 deployment, compute the predicted address and check if code already exists. If so, return the existing address instead of reverting:

```solidity
function deploy(address _mainModule, bytes32 _salt) public payable returns (address _contract) {
    bytes memory code = abi.encodePacked(Wallet.creationCode, uint256(uint160(_mainModule)));
    _contract = address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt, keccak256(code))))));

    if (_contract.code.length > 0) {
        return _contract; // Already deployed, return existing address
    }

    assembly {
        _contract := create2(callvalue(), add(code, 32), mload(code), _salt)
    }
    if (_contract == address(0)) {
        revert DeployFailed(_mainModule, _salt);
    }
}
```

Modify `_incomingTokenBalance()` to return the minimum of allowance and actual balance:

```solidity
function _incomingTokenBalance() internal view virtual override returns (uint256) {
    uint256 allowance = erc20Token.allowance(msg.sender, address(this));
    uint256 balance = erc20Token.balanceOf(msg.sender);
    return allowance >= balance ? balance : allowance;
}
```

This ensures the function returns the maximum transferable amount, which is the lesser of what the user has approved and what they actually own.
